const fs=require('fs'),path=require('path'),crypto=require('crypto');
const CONTRACT_PATH='pls_v16/BINDING_CONTRACT.json',CONTRACT_SHA='6e8558b4545c1084b3a8342eb2f66611de97dc2e78db46f60919666313164140';
const PACK=process.env.PLS_V16_PACK_DIR||'wip-pls-v16-vector-sharded',META=process.env.PLS_V16_METADATA||'wip-current-semantic-pack/metadata.jsonl',MASK=process.env.PLS_V16_MASK||'wip-current-semantic-pack/jesus_mask.bits',CAL=process.env.PLS_V16_CALIBRATION||'wip-pls-v16-calibration/calibration_evidence.json',OUT=process.env.PLS_V16_MANIFEST_OUT||'wip-pls-v16-manifest';
const ok=(c,m)=>{if(!c)throw new Error(m)},sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'),desc=(p,canonical)=>({path:canonical,bytes:fs.statSync(p).size,sha256:sha(p)});
ok(sha(CONTRACT_PATH)===CONTRACT_SHA,'CONTRACT_SHA');const C=JSON.parse(fs.readFileSync(CONTRACT_PATH,'utf8'));fs.mkdirSync(OUT,{recursive:true});
const V=path.join(PACK,'vectors.i8'),N=path.join(PACK,'inverse_norms.f32le');for(const p of [V,N,META,MASK,CAL])ok(fs.existsSync(p),'INPUT_MISSING '+p);
ok(fs.statSync(V).size===C.chunker.expected_passages*C.model.embedding_dim,'VECTOR_BYTES');ok(fs.statSync(N).size===C.chunker.expected_passages*4,'NORM_BYTES');ok(fs.statSync(MASK).size===Math.ceil(C.chunker.expected_passages/8),'MASK_BYTES');
const rows=fs.readFileSync(META,'utf8').trimEnd().split(/\r?\n/).filter(Boolean).map(JSON.parse);ok(rows.length===C.chunker.expected_passages,'METADATA_ROWS');const docs=JSON.parse(fs.readFileSync('corpus/search_v2_documents.json','utf8')).documents;ok(docs.length===C.corpus_population.documents,'CURRENT_DOCS');
const covered=new Uint8Array(docs.length);for(const r of rows)for(const s of (r.source_spans||[])){const di=Number(s.doc_index);ok(Number.isInteger(di)&&di>=0&&di<docs.length,'SOURCE_SPAN_DOC_INDEX');covered[di]=1;}let coveredCount=0;for(const x of covered)coveredCount+=x?1:0;const missing=docs.length-coveredCount;ok(coveredCount===docs.length&&missing===0,'COVERAGE_NOT_COMPLETE');
let jesus=0;const mask=fs.readFileSync(MASK);for(let i=0;i<rows.length;i++)if(mask[i>>3]&(1<<(i&7)))jesus++;ok(jesus===20098,'JESUS_MASK_COUNT '+jesus);
const cal=JSON.parse(fs.readFileSync(CAL,'utf8'));ok(cal.binding_contract_sha256===CONTRACT_SHA&&cal.pack_id===C.pack_id,'CALIBRATION_BINDING');const gates=cal.gates||{},qualified=cal.status==='PASS_QUALIFIABLE'&&gates.owner_real_query_gate==='PASS'&&gates.hard_negative_gate==='PASS'&&gates.blind_challenge_gate==='PASS'&&cal.selection&&cal.selection.policy&&cal.selection.policy.policy_id==='HYBRID_DENSE_ABSTENTION_V1';
const coverage={schema:'ldc-pls-v16-coverage-proof-v1',binding_contract_sha256:CONTRACT_SHA,pack_id:C.pack_id,current_documents:docs.length,covered_documents:coveredCount,missing_documents:missing,status:'PASS',metadata_sha256:sha(META),search_documents_sha256:C.bindings.search_documents_sha256};
const covPath=path.join(OUT,'coverage.json');fs.writeFileSync(covPath,JSON.stringify(coverage,null,2)+'\n');
const files=[...C.model.tokenizer_and_config_files,...C.model.delivery.parts,...C.runtime.files,desc(META,'pls_v16/pack/metadata.jsonl'),desc(V,'pls_v16/pack/vectors.i8'),desc(N,'pls_v16/pack/inverse_norms.f32le'),desc(MASK,'pls_v16/pack/jesus_mask.bits'),desc(covPath,'pls_v16/evidence/coverage.json'),desc(CAL,'pls_v16/evidence/calibration_evidence.json')];
const manifest={schema:'ldc-search-v3-semantic-pack-r3',pack_id:C.pack_id,binding_contract_sha256:CONTRACT_SHA,status:qualified?'QUALIFIED__ACTIVATION_ELIGIBLE_AFTER_GUARD_VERIFICATION':'ENGINEERING_ONLY__NOT_ACTIVATABLE',bindings:C.bindings,chunker:{mode:C.chunker.mode,policy_id:C.chunker.policy_id,window_words:C.chunker.window_words,stride_words:C.chunker.stride_words,tail_anchor:C.chunker.tail_anchor,expected_passages:C.chunker.expected_passages},model:{model_id:C.model.model_id,immutable_revision:C.model.immutable_revision,model_sha256:C.model.model_sha256,embedding_dim:C.model.embedding_dim,pooling:C.model.pooling,normalization:C.model.normalization,query_prefix:C.model.query_prefix,passage_prefix:C.model.passage_prefix,max_length:C.model.max_length,tokenizer_files:C.model.tokenizer_and_config_files,delivery:C.model.delivery},index:{rows:rows.length,cols:C.model.embedding_dim,dtype:'int8_row_symmetric',vectors_file:files.find(x=>x.path==='pls_v16/pack/vectors.i8'),metadata_file:files.find(x=>x.path==='pls_v16/pack/metadata.jsonl'),inverse_norms_file:files.find(x=>x.path==='pls_v16/pack/inverse_norms.f32le')},speaker_filter:{rows:rows.length,mode:'enriched',policy_id:C.chunker.policy_id,rule:'HIGH_CONFIDENCE_JESUS_CANONICAL_SPAN_OVERLAP_GT_0',eligible_count:jesus,jesus_mask_file:files.find(x=>x.path==='pls_v16/pack/jesus_mask.bits')},runtime:{engine:'transformers.js+onnxruntime-web',version:'3.8.1',files:C.runtime.files},retrieval:C.retrieval,coverage:{status:'PASS',current_documents:docs.length,covered_documents:coveredCount,missing_documents:missing,proof_file:files.find(x=>x.path==='pls_v16/evidence/coverage.json')},calibration:{status:qualified?'QUALIFIED':'ENGINEERING_ONLY',owner_real_query_gate:gates.owner_real_query_gate||'FAIL',hard_negative_gate:gates.hard_negative_gate||'FAIL',blind_challenge_gate:gates.blind_challenge_gate||'FAIL',hybrid_policy:qualified?cal.selection.policy:null,evidence_file:files.find(x=>x.path==='pls_v16/evidence/calibration_evidence.json')},files,deployment_authorized:false,app_runtime_wired:false};
const mp=path.join(OUT,'semantic_pack_manifest.json');fs.writeFileSync(mp,JSON.stringify(manifest,null,2)+'\n');const report={schema:'ldc-pls-v16-manifest-build-v1',status:qualified?'QUALIFIED_MANIFEST_BUILT__NOT_DEPLOYED':'ENGINEERING_MANIFEST_BUILT__NOT_ACTIVATABLE',manifest_sha256:sha(mp),manifest_bytes:fs.statSync(mp).size,qualification_source_status:cal.status,gates,coverage:{documents:docs.length,covered:coveredCount,missing},jesus_eligible:jesus,deployment_authorized:false};fs.writeFileSync(path.join(OUT,'manifest_build_report.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));if(!qualified)process.exitCode=4;
